/**
 * 01 检查执行记录（手动重新识别 / Webhook 单条触发版）
 *
 * 【原理】
 * 1. feishu-listener 命中 Bill-Re-identification 规则后，POST 到 n8n Webhook。
 * 2. n8n Webhook 节点收到的 item 结构通常是：
 *    { headers, body: { route_name, event: { resource, raw, ... } }, ... }
 * 3. 本节点不再依赖「查询飞书 Search Records」的 record.fields，
 *    而是从 event.raw.event.action_list[0].after_value 读取变更后的字段快照。
 * 4. after_value 里是 field_id + field_value（飞书内部格式），需按字段 ID 解析。
 * 5. 解析完成后输出与批量工作流相同的 json，后续 Switch / 获取关联订单 等节点无需改动。
 */

// 执行表 tbl821KbTBpjjyXI 字段 ID（与飞书多维表 / feishu-listener 一致）
const FIELD = {
  关联订单: 'fld56wUBzA',   // 双向关联 → 订单表 record_id 数组
  执行编号: 'fldKUOt2nO',   // 自动编号 → [{ number, sequence }]
  执行人数: 'fldw1TGVjD',   // 数字
  执行日期: 'fldwssO4L7',   // 日期 → { bus_type:[5], data:[{ value: 毫秒时间戳 }] }
};

/** 兼容 n8n Webhook 不同挂载方式：payload 可能在 body 内，也可能在根级 */
function unwrapWebhook(input) {
  if (input?.body?.event) return input.body;
  if (input?.body?.route_name && input?.body?.event) return input.body;
  if (input?.event) return input;
  return input;
}

/** 从 feishu-listener 标准化 event 里取 action_list */
function getActionList(payload) {
  const list = payload?.event?.raw?.event?.action_list;
  return Array.isArray(list) ? list : [];
}

/** record_id 优先取 resource，其次 action_list */
function getRecordId(payload, actionList) {
  const fromResource = payload?.event?.resource?.record_id;
  if (fromResource) return String(fromResource).trim();
  const fromAction = actionList[0]?.record_id;
  return fromAction ? String(fromAction).trim() : '';
}

/** 将 after_value 数组转为 field_id → field_value 映射 */
function buildFieldMap(afterValue) {
  const map = {};
  if (!Array.isArray(afterValue)) return map;
  for (const item of afterValue) {
    const id = item?.field_id;
    if (id) map[id] = item.field_value ?? '';
  }
  return map;
}

function parseJsonSafe(raw) {
  if (raw == null || raw === '') return null;
  if (typeof raw === 'object') return raw;
  try {
    return JSON.parse(String(raw));
  } catch (_) {
    return null;
  }
}

/** 执行编号："[{\"number\":\"ZX26060911\",\"sequence\":\"911\"}]" → ZX26060911 */
function pickExecNo(raw) {
  const data = parseJsonSafe(raw);
  if (Array.isArray(data) && data.length) {
    const num = data[0]?.number ?? data[0]?.text;
    if (num) return String(num).trim();
  }
  return String(raw || '').trim();
}

/** 关联订单："[\"recvne7ErMlVx5\"]" → linkedOrderId */
function pickLinkIds(raw) {
  const data = parseJsonSafe(raw);
  if (Array.isArray(data)) {
    return data.map((x) => String(x).trim()).filter(Boolean);
  }
  return [];
}

/** 执行人数：可能是 "40" 或数字 */
function pickExecPeople(raw) {
  if (raw == null || raw === '') return '';
  const n = Number(raw);
  if (!Number.isNaN(n)) return String(n);
  return String(raw).trim();
}

/** 执行日期：bus_type=5 的毫秒时间戳 → YYYY-MM-DD */
function pickExecDate(raw) {
  const data = parseJsonSafe(raw);
  if (data && Array.isArray(data.data) && data.data[0]?.value != null) {
    const ts = Number(data.data[0].value);
    if (!Number.isNaN(ts)) {
      return new Date(ts).toISOString().slice(0, 10);
    }
  }
  const n = Number(raw);
  if (!Number.isNaN(n) && n > 1e11) {
    return new Date(n).toISOString().slice(0, 10);
  }
  return String(raw || '').trim();
}

// ── 主流程 ────────────────────────────────────────────────

const payload = unwrapWebhook($json);
const actionList = getActionList(payload);
const record_id = getRecordId(payload, actionList);

// after_value = 本次编辑后该行的字段快照（含未变更字段）
const afterValue = actionList[0]?.after_value || [];
const fieldMap = buildFieldMap(afterValue);

const linkedOrderIds = pickLinkIds(fieldMap[FIELD.关联订单]);
const hasLinkedOrder = linkedOrderIds.length > 0;

let noContractReason = '';
if (!record_id) {
  noContractReason = 'Webhook 未解析到执行记录 record_id';
} else if (!hasLinkedOrder) {
  noContractReason = '执行记录缺少关联订单';
}

return {
  json: {
    record_id,
    execNo: pickExecNo(fieldMap[FIELD.执行编号]),
    执行人数: pickExecPeople(fieldMap[FIELD.执行人数]),
    执行日期: pickExecDate(fieldMap[FIELD.执行日期]),
    hasLinkedOrder,
    noContractReason,
    linkedOrderId: linkedOrderIds[0] || '',
  },
};

