function aggregateField(pages, field) {
  let hasYes = false;
  let hasUncertain = false;
  for (const page of pages) {
    const val = normalizeYesNo(page[field]);
    if (val === '是') hasYes = true;
    else if (val === '不确定') hasUncertain = true;
  }
  if (hasYes) return '是';
  if (hasUncertain) return '不确定';
  return '否';
}

